import{_ as t,o as a,c as e,ae as n}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"设计趋势 - 2026-06-11","description":"","frontmatter":{"date":"2026-06-11T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-06-11-uxtrend.md","filePath":"daily/2026-06-11-uxtrend.md"}'),o={name:"daily/2026-06-11-uxtrend.md"};function s(i,r,g,p,h,l){return a(),e("div",null,[...r[0]||(r[0]=[n('<h1 id="设计趋势-2026-06-11" tabindex="-1">设计趋势 - 2026-06-11 <a class="header-anchor" href="#设计趋势-2026-06-11" aria-label="Permalink to &quot;设计趋势 - 2026-06-11&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势领域聚焦于AI在工作流程中的应用和用户体验。AI代理工作流设计模式被强调，旨在协调任务。最值得关注的是AI在提升用户信任和个性化产品设计方面的作用。AI通过透明度和可逆性原则增强信任，并利用数据分析助力设计师实现个性化设计。</p><hr><h3 id="_1-ai代理工作流设计模式概览" tabindex="-1">1. AI代理工作流设计模式概览 <a class="header-anchor" href="#_1-ai代理工作流设计模式概览" aria-label="Permalink to &quot;1. AI代理工作流设计模式概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/binome/ai-agent-workflow-design-patterns-an-overview-cf9e1f609696" target="_blank" rel="noreferrer">AI Agent Workflow Design Patterns — An Overview | by Craig Li, Ph.D</a></p><p><strong>一句话摘要</strong>: 探讨AI代理工作流设计模式，强调工作流作为任务协调器。</p><p><strong>能解决什么问题</strong>: 模拟人类推理，通过工作流设计模式提升AI代理的规划和执行能力。</p><p><strong>产品应用</strong>: 可以应用于开发智能代理产品，通过工作流设计模式灵活处理不同问题。</p><p><strong>示例场景</strong>: 智能客服代理通过工作流设计模式处理客户咨询。</p><hr><h3 id="_2-设计值得信赖的ai代理-30-ux原则将-惊叹-转变为日常习惯" tabindex="-1">2. 设计值得信赖的AI代理：30+ UX原则将“惊叹”转变为日常习惯 <a class="header-anchor" href="#_2-设计值得信赖的ai代理-30-ux原则将-惊叹-转变为日常习惯" aria-label="Permalink to &quot;2. 设计值得信赖的AI代理：30+ UX原则将“惊叹”转变为日常习惯&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/techacc/designing-trustworthy-ai-agents-30-ux-principles-that-turn-wow-into-daily-habit-223da9f4d7f2" target="_blank" rel="noreferrer">Designing Trustworthy AI Agents: 30+ UX Principles that Turn “Wow” into Daily Habit</a></p><p><strong>一句话摘要</strong>: 通过透明度和可逆性原则，提升用户对AI代理的信任。</p><p><strong>能解决什么问题</strong>: 用户对AI代理的不信任和“黑箱焦虑”问题。</p><p><strong>产品应用</strong>: 适用于需要用户信任和依赖AI代理的产品，如智能助手、自动化服务。</p><p><strong>示例场景</strong>: 智能助手自动发送工资单，用户可实时查看状态和决策日志。</p><hr><h3 id="_3-ai在设计中的应用-改变我们的创造方式" tabindex="-1">3. AI在设计中的应用：改变我们的创造方式 <a class="header-anchor" href="#_3-ai在设计中的应用-改变我们的创造方式" aria-label="Permalink to &quot;3. AI在设计中的应用：改变我们的创造方式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/resource-library/ai-in-design" target="_blank" rel="noreferrer">AI in Design: Transforming the Way We Create | Figma</a></p><p><strong>一句话摘要</strong>: AI将深度整合进设计工作流程，提升团队协作和创意适应性。</p><p><strong>能解决什么问题</strong>: 解决设计过程中的自动化和个性化需求，提高效率。</p><p><strong>产品应用</strong>: 可应用于产品设计，通过AI生成个性化界面和优化工作流程。</p><p><strong>示例场景</strong>: 使用AI设计工具根据用户行为自动调整界面布局。</p><hr><h3 id="_4-ai交互模式-让用户识别并互动ai驱动功能" tabindex="-1">4. AI交互模式：让用户识别并互动AI驱动功能 <a class="header-anchor" href="#_4-ai交互模式-让用户识别并互动ai驱动功能" aria-label="Permalink to &quot;4. AI交互模式：让用户识别并互动AI驱动功能&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@flik185/ai-interaction-patterns-giving-users-ways-to-recognize-and-interact-with-ai-driven-features-22055a91206b" target="_blank" rel="noreferrer">AI Interaction Patterns: Giving Users Ways to Recognize and Interact With Ai-Driven Features</a></p><p><strong>一句话摘要</strong>: 通过交互模式建立人与AI之间的信任关系。</p><p><strong>能解决什么问题</strong>: 如何让用户识别并有效互动AI驱动的功能。</p><p><strong>产品应用</strong>: 适用于AI工具，如聊天机器人、分析仪表板等。</p><p><strong>示例场景</strong>: 聊天机器人中提示用户如何提问以获得最佳回答。</p><hr><h3 id="_5-利用ai实现更智能的产品设计" tabindex="-1">5. 利用AI实现更智能的产品设计 <a class="header-anchor" href="#_5-利用ai实现更智能的产品设计" aria-label="Permalink to &quot;5. 利用AI实现更智能的产品设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/glow-team/leveraging-ai-for-smarter-product-design-9ba3de816f28" target="_blank" rel="noreferrer">Leveraging AI for Smarter Product Design</a></p><p><strong>一句话摘要</strong>: AI通过数据分析助力设计师理解用户需求，实现个性化产品设计。</p><p><strong>能解决什么问题</strong>: 解决设计师依赖猜测而非数据做决策的问题。</p><p><strong>产品应用</strong>: 可以应用到实际产品中，通过AI分析数据来指导设计决策。</p><p><strong>示例场景</strong>: AI设计可调节形状的鞋子以适应不同脚型。</p><hr><h3 id="_6-构建信任与增强互动-7个关键的ai-ux模式" tabindex="-1">6. 构建信任与增强互动：7个关键的AI UX模式 <a class="header-anchor" href="#_6-构建信任与增强互动-7个关键的ai-ux模式" aria-label="Permalink to &quot;6. 构建信任与增强互动：7个关键的AI UX模式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/bestfolios/building-trust-and-enhancing-interactions-7-essential-ai-ux-patterns-in-action-12e7604de435" target="_blank" rel="noreferrer">Building Trust and Enhancing Interactions: 7 Essential AI UX Patterns in Action</a></p><p><strong>一句话摘要</strong>: 文章介绍了7个提升AI交互体验的UX模式。</p><p><strong>能解决什么问题</strong>: 提高AI工具的易用性、效率和用户信任度。</p><p><strong>产品应用</strong>: 适用于需要增强用户交互和提升效率的AI产品。</p><p><strong>示例场景</strong>: ChatGPT的智能代码块允许用户直接复制和运行代码。</p><hr><h3 id="_7-实施有效的ai工作流自动化的20个技巧" tabindex="-1">7. 实施有效的AI工作流自动化的20个技巧 <a class="header-anchor" href="#_7-实施有效的ai工作流自动化的20个技巧" aria-label="Permalink to &quot;7. 实施有效的AI工作流自动化的20个技巧&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/predict/20-tips-for-implementing-effective-ai-workflow-automations-2fe365bcaa48" target="_blank" rel="noreferrer">20 Tips for Implementing Effective AI Workflow Automations | by Dr. Brian Scott Glassman | Predict | Medium</a></p><p><strong>一句话摘要</strong>: 优化AI工作流自动化，提高效率和降低成本。</p><p><strong>能解决什么问题</strong>: 解决AI工作流自动化中的效率和成本问题。</p><p><strong>产品应用</strong>: 适用于需要自动化处理大量常规工作流程的企业。</p><p><strong>示例场景</strong>: 客户服务部门使用AI自动化处理常见查询。</p><hr><h3 id="_8-2026年顶级网页设计趋势-figma" tabindex="-1">8. 2026年顶级网页设计趋势 - Figma <a class="header-anchor" href="#_8-2026年顶级网页设计趋势-figma" aria-label="Permalink to &quot;8. 2026年顶级网页设计趋势 - Figma&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/resource-library/web-design-trends" target="_blank" rel="noreferrer">Top Web Design Trends for 2026 - Figma</a></p><p><strong>一句话摘要</strong>: AI技术正在使网站设计更智能、个性化。</p><p><strong>能解决什么问题</strong>: 提高网站交互性、可访问性和个性化体验。</p><p><strong>产品应用</strong>: 可以应用到实际产品中，通过Figma Make等工具实现智能布局和交互。</p><p><strong>示例场景</strong>: 使用Figma Make设计聊天机器人以提升用户体验。</p><hr><h3 id="_9-为代理式用户体验设计指南" tabindex="-1">9. 为代理式用户体验设计指南 <a class="header-anchor" href="#_9-为代理式用户体验设计指南" aria-label="Permalink to &quot;9. 为代理式用户体验设计指南&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/ai-ux-designers/era-of-agentive-ux-not-agentic-64dd765a0372" target="_blank" rel="noreferrer">Designing for Agentive UX — A Guide | by Kshitij Agrawal - Medium</a></p><p><strong>一句话摘要</strong>: 设计代理式用户体验，以预测并满足用户未知需求。</p><p><strong>能解决什么问题</strong>: 解决用户寻找未知未来信息的需求问题。</p><p><strong>产品应用</strong>: 可应用于智能助手，通过持续学习用户行为提供个性化服务。</p><p><strong>示例场景</strong>: 智能助手根据用户兴趣自动推荐未来可能感兴趣的内容。</p><hr><h3 id="_10-设计师作为协调者-不确定的人工智能-使用cursor设计工具-以及ux如何影响损益表" tabindex="-1">10. 设计师作为协调者，不确定的人工智能，使用Cursor设计工具，以及UX如何影响损益表 <a class="header-anchor" href="#_10-设计师作为协调者-不确定的人工智能-使用cursor设计工具-以及ux如何影响损益表" aria-label="Permalink to &quot;10. 设计师作为协调者，不确定的人工智能，使用Cursor设计工具，以及UX如何影响损益表&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uxdesign.cc/designers-as-orchestrators-uncertain-ai-designing-with-cursor-how-ux-impacts-p-l-557ef6c89e62" target="_blank" rel="noreferrer">Designers as orchestrators, uncertain AI, designing with Cursor, how UX impacts P&amp;L</a></p><p><strong>一句话摘要</strong>: 探讨设计师在AI时代的角色转变，以及UX设计对企业财务的直接影响。</p><p><strong>能解决什么问题</strong>: 解决非技术背景人士无法快速获得定制软件工具的问题。</p><p><strong>产品应用</strong>: 可应用于产品设计，通过AI提升用户体验，间接影响企业利润。</p><p><strong>示例场景</strong>: 使用Cursor设计工具，快速创建符合用户需求的界面。</p><hr>',75)])])}const u=t(o,[["render",s]]);export{c as __pageData,u as default};
